/**
 * @method
 * @name scwin.changeInqdisclsInfo
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.changeInqdisclsInfo = function () {
    /* sdd-asis-lifecycle:begin changeInqdisclsInfo — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const formUpclssCd = $c.util.getComponent('slc_formUpclssCd').getValue();
    const rsnClssCd = $c.util.getComponent('slc_rsnClssCd').getValue();
    if ((formUpclssCd === "01" && rsnClssCd === "040") || (formUpclssCd === "01" && rsnClssCd === "041") || (formUpclssCd === "09" && rsnClssCd === "006") || (formUpclssCd === "09" && rsnClssCd === "009")) {
        $c.util.getComponent('slc_inqdisclsTpCd').setDisabled(false);
        $c.util.getComponent('slc_inqdisclsContnTpCd').setDisabled(false);
        scwin.changeInqdisclsInfo2();
    } else {
        $c.util.getComponent('slc_inqdisclsTpCd').setDisabled(true);
        $c.util.getComponent('slc_inqdisclsContnTpCd').setDisabled(true);
        $c.util.getComponent('slc_inqdisclsAnsTpCd').setDisabled(true);
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.changeInqdisclsInfo2
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.changeInqdisclsInfo2 = function () {
    /* sdd-asis-lifecycle:begin changeInqdisclsInfo2 — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if ($c.util.getComponent('slc_inqdisclsTpCd').getValue() === "A") {
        $c.util.getComponent('slc_inqdisclsAnsTpCd').setDisabled(false);
    } else {
        $c.util.getComponent('slc_inqdisclsAnsTpCd').setDisabled(true);
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.findRsnClasses
 * @author Inswave
 * @date 2026. 09. 29
 * @param
