/**
 * @method
 * @name scwin.selectedClass
 * @author Inswave
 * @date 2026. 09. 29
 * @param objNm
 * @returns
 * @hidden N
*/
scwin.selectedClass = function (objNm) {
    /* sdd-asis-lifecycle:begin selectedClass — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const _options = eval("editForm." + objNm).options;
    const optVal = $c.util.getComponent('slc_rsnClssCd').getValue();
    for (let i = 0; i < _options.length; i++) {
        if (_options[i].value === optVal) {
            _options[i].selected = true;
            break;
        }
    }
    /* sdd-asis-lifecycle:end */
};
